#include <iostream>
#include <vector>

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        std::cin >> value;
        values.push_back(value);
    }
    long long total = 0;
    int best = values[0];
    for (int value : values) {
        total += value;
        if (value > best) {
            best = value;
        }
    }
    std::cout << total << std::endl;
    std::cout << best << std::endl;
    return 0;
}
